<script setup>
import { onMounted, reactive, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import { getAdminRestaurants, updateAdminRestaurantStatus } from '../../services/admin'
import { useToastStore } from '../../stores/toast'
import BaseAlert from '../../components/ui/BaseAlert.vue'
import BaseBadge from '../../components/ui/BaseBadge.vue'
import BaseButton from '../../components/ui/BaseButton.vue'
import BaseConfirmDialog from '../../components/ui/BaseConfirmDialog.vue'
import BaseEmptyState from '../../components/ui/BaseEmptyState.vue'
import BaseLoading from '../../components/ui/BaseLoading.vue'

const { t } = useI18n(); const toast = useToastStore(); const loading = ref(true); const error = ref(''); const restaurants = ref([]); const meta = ref({}); const filters = reactive({ search: '', status: '', sort: 'newest', page: 1 }); const selected = ref(null); const saving = ref(false)
async function load() { loading.value = true; error.value = ''; try { const data = await getAdminRestaurants(filters); restaurants.value = data.restaurants; meta.value = data.meta } catch { error.value = 'admin.loadError' } finally { loading.value = false } }
async function confirmStatus() { saving.value = true; try { const status = selected.value.platform_status === 'active' ? 'suspended' : 'active'; const updated = await updateAdminRestaurantStatus(selected.value.id, status); restaurants.value = restaurants.value.map((item) => item.id === updated.id ? updated : item); toast.success(t(status === 'active' ? 'admin.restaurantReactivated' : 'admin.restaurantSuspended')); selected.value = null } catch { toast.error(t('admin.updateError')) } finally { saving.value = false } }
onMounted(load)
</script>

<template><section class="admin-page"><header class="page-heading"><div><h1>{{ $t('admin.restaurants') }}</h1><p>{{ $t('admin.restaurantsIntro') }}</p></div></header><form class="admin-filters" @submit.prevent="filters.page = 1; load()"><label>{{ $t('admin.search') }}<input v-model="filters.search" type="search"></label><label>{{ $t('admin.status') }}<select v-model="filters.status"><option value="">{{ $t('admin.all') }}</option><option value="active">{{ $t('admin.active') }}</option><option value="inactive">{{ $t('admin.inactive') }}</option><option value="suspended">{{ $t('admin.suspended') }}</option></select></label><label>{{ $t('admin.sort') }}<select v-model="filters.sort"><option value="newest">{{ $t('admin.newest') }}</option><option value="oldest">{{ $t('admin.oldest') }}</option><option value="name">{{ $t('admin.name') }}</option></select></label><BaseButton type="submit">{{ $t('admin.apply') }}</BaseButton></form><BaseAlert v-if="error" type="error">{{ $t(error) }}</BaseAlert><BaseLoading v-if="loading" :rows="5" /><BaseEmptyState v-else-if="!restaurants.length" :title="$t('admin.noRestaurants')" :message="$t('admin.noRestaurantsHelp')" /><div v-else class="admin-table-wrap"><table><caption class="sr-only">{{ $t('admin.restaurantsTableCaption') }}</caption><thead><tr><th>{{ $t('admin.name') }}</th><th>{{ $t('admin.owner') }}</th><th>{{ $t('admin.status') }}</th><th>{{ $t('admin.categories') }} / {{ $t('admin.menuItems') }}</th><th>{{ $t('admin.views') }}</th><th>{{ $t('admin.created') }}</th><th>{{ $t('admin.actions') }}</th></tr></thead><tbody><tr v-for="restaurant in restaurants" :key="restaurant.id"><td><strong>{{ restaurant.name_ar || restaurant.name_en || restaurant.name }}</strong><small>{{ restaurant.slug }}</small></td><td>{{ restaurant.owner?.email }}</td><td><BaseBadge :variant="restaurant.platform_status === 'active' ? 'success' : 'danger'">{{ $t(`admin.${restaurant.platform_status}`) }}</BaseBadge><small>{{ $t(restaurant.is_active ? 'admin.ownerPublished' : 'admin.ownerUnpublished') }}</small></td><td>{{ restaurant.categories_count }} / {{ restaurant.menu_items_count }}</td><td>{{ restaurant.public_menu_views }}</td><td>{{ new Date(restaurant.created_at).toLocaleDateString() }}</td><td class="table-actions"><RouterLink class="ui-button ui-button-ghost" :to="{ name: 'admin-restaurant-detail', params: { id: restaurant.id } }">{{ $t('admin.viewDetails') }}</RouterLink><a class="ui-button ui-button-ghost" :href="`/menu/${restaurant.slug}`" target="_blank" rel="noopener">{{ $t('admin.openPublicMenu') }}</a><BaseButton :variant="restaurant.platform_status === 'active' ? 'danger' : 'primary'" @click="selected = restaurant">{{ $t(restaurant.platform_status === 'active' ? 'admin.suspend' : 'admin.reactivate') }}</BaseButton></td></tr></tbody></table></div><div v-if="meta.last_page > 1" class="pagination"><BaseButton variant="ghost" :disabled="meta.current_page <= 1" @click="filters.page--; load()">{{ $t('admin.previous') }}</BaseButton><span>{{ meta.current_page }} / {{ meta.last_page }}</span><BaseButton variant="ghost" :disabled="meta.current_page >= meta.last_page" @click="filters.page++; load()">{{ $t('admin.next') }}</BaseButton></div><BaseConfirmDialog :open="Boolean(selected)" :loading="saving" danger :message="$t(selected?.platform_status === 'active' ? 'admin.suspendRestaurantConfirm' : 'admin.reactivateRestaurantConfirm')" @confirm="confirmStatus" @cancel="selected = null" /></section></template>
